def canSlideTransform(start, end):
    n = len(start)
    if n != len(end):
        return False
    i = j = 0
    while True:
        while i < n and start[i] == 'X':
            i += 1
        while j < n and end[j] == 'X':
            j += 1
        if i == n or j == n:
            return i == n and j == n
        if start[i] != end[j]:
            return False
        if start[i] == 'L' and i < j:
            return False
        if start[i] == 'R' and i > j:
            return False
        i += 1
        j += 1
